const $=id=>document.getElementById(id),money=n=>Math.round(n).toLocaleString('ko-KR')+'원';
const requestedStock = new URLSearchParams(location.search).get('stock');
if (/^[0-2]$/.test(requestedStock || '')) $('stock').value = requestedStock;
let account=DemoStore.initial(),side='buy',pending=null,processing=false,storageError='연습 기록을 불러오는 중입니다.';
function refresh(){try{account=DemoStore.read();storageError='';}catch(e){storageError=e.message;}if($('confirm').open){$('confirm').close();pending=null;}render();renderHistory();if(storageError)$('result').textContent=storageError;}
function totals(stock,q){return DemoStore.quote(account,account.holdings.indexOf(stock),q,side);}
function errorFor(stock,q){return storageError||DemoStore.check(account,account.holdings.indexOf(stock),q,side);}
function maxQuantity(stock){if(storageError)return 0;if(side==='sell')return stock.quantity;let low=0,high=Math.floor(account.cash/stock.price);while(low<high){const mid=Math.ceil((low+high)/2);if(errorFor(stock,mid))high=mid-1;else low=mid;}return low;}
function render(){const stock=account.holdings[Number($('stock').value)],q=$('quantity').value.trim()===''?NaN:Number($('quantity').value),error=errorFor(stock,q);let t=null;try{t=totals(stock,q);}catch{}pending=null;$('price').textContent=money(stock.price);$('held').textContent=stock.quantity+'주';$('buy').setAttribute('aria-pressed',String(side==='buy'));$('sell').setAttribute('aria-pressed',String(side==='sell'));$('quantity-hint').textContent=`지금 ${side==='buy'?'살':'팔'} 수 있는 최대 수량: ${maxQuantity(stock)}주`;$('error').textContent=error;$('quantity').setAttribute('aria-invalid',String(Boolean(error)));for(const key of ['gross','fee','tax','settlement'])$(key).textContent=t?money(t[key]):'—';$('tax-row').hidden=side!=='sell';$('total-label').textContent=side==='buy'?'총 결제 금액':'받을 금액 (비용 제외 후)';$('cash').textContent=money(account.cash);$('after').textContent=!error?money(side==='buy'?account.cash-t.settlement:account.cash+t.settlement):'—';$('review').textContent=side==='buy'?'매수 내용 확인':'매도 내용 확인';$('review').disabled=Boolean(error)||processing;}
function renderHistory(){$('history').replaceChildren();for(const order of account.orders.slice(-5).reverse()){const li=document.createElement('li');li.textContent=`${order.name} ${order.q}주 ${order.side==='buy'?'매수':'매도'} 연습 완료`;const detail=document.createElement('small');detail.textContent=`${order.side==='buy'?'결제':'받은'} 금액 ${money(order.settlement)} · ${new Date(order.at).toLocaleString('ko-KR')}`;li.append(detail);$('history').append(li);}$('empty').hidden=account.orders.length>0;}
function setQuantity(q){$('quantity').value=String(q);render();}
$('stock').addEventListener('change',()=>setQuantity(1));$('quantity').addEventListener('input',render);$('buy').addEventListener('click',()=>{side='buy';render();});$('sell').addEventListener('click',()=>{side='sell';render();});$('minus').addEventListener('click',()=>setQuantity(Math.max(1,(Number($('quantity').value)||1)-1)));$('plus').addEventListener('click',()=>setQuantity((Number($('quantity').value)||0)+1));$('one').addEventListener('click',()=>setQuantity(1));$('ten').addEventListener('click',()=>setQuantity(10));$('max').addEventListener('click',()=>setQuantity(maxQuantity(account.holdings[Number($('stock').value)])));
$('review').addEventListener('click',async()=>{if(processing||storageError)return;processing=true;$('review').disabled=true;try{await AppAccount.refresh();}catch(e){$('result').textContent=e.message;processing=false;render();return;}processing=false;refresh();const index=Number($('stock').value),q=Number($('quantity').value),stock=account.holdings[index];if(errorFor(stock,q))return;pending={id:crypto.randomUUID(),index,q,side,revision:account.revision,...totals(stock,q)};$('confirm-text').textContent=`${stock.name} ${q}주 ${side==='buy'?'매수':'매도'} · ${side==='buy'?'결제':'받을'} 금액 ${money(pending.settlement)} (수수료 ${money(pending.fee)}${side==='sell'?', 세금 '+money(pending.tax):''})`;$('confirm').showModal();});
$('cancel').addEventListener('click',()=>{$('confirm').close();pending=null;});$('confirm').addEventListener('cancel',()=>{pending=null;});
$('complete').addEventListener('click',async()=>{if(processing||!pending)return;processing=true;$('complete').disabled=true;const order=pending;pending=null;try{await DemoStore.execute({id:order.id,index:order.index,q:order.q,side:order.side},order.revision);$('result').textContent='연습 주문을 저장했습니다. 투자 현황과 주문내역에도 반영됩니다.';}catch(e){$('result').textContent=e.message;try{await AppAccount.refresh();}catch{}}finally{processing=false;$('complete').disabled=false;$('confirm').close();refresh();}});
$('review').disabled=true;AppAccount.ready.then(()=>{DemoStore.subscribe(refresh);refresh();}).catch(e=>{storageError=e.message;render();$('result').textContent=e.message;});

